 <section class="detail-section"><h3>Informações do aceite</h3><div class="courier-line"><div class="avatar">${esc(courier?.name?.slice(0,1).toUpperCase()||'?')}</div><div><span>Entregador</span><b>${esc(courier?.name||'Ainda não atribuído')}</b><small>${esc(courier?.phone||'')}</small></div></div><div class="detail-grid"><div><span>Momento do aceite</span><b>${o.courier?date(o.updated_at):'—'}</b></div><div><span>Distância estimada</span><b>${km} km</b></div><div><span>Tempo estimado</span><b>${minutes} min</b></div></div>${o.status==='requested'?`<label class="dispatch-select">Entregador disponível<select id="assign-courier"><option value="">Selecione</option>${members('courier').filter(m=>statusOf(m)==='active'&&m.is_available).map(m=>`<option value="${m.user_id}">${esc(m.name)} · ${esc(m.city)}</option>`).join('')}</select></label>`:''}</section>
