 const paintTabs=()=>{const c=counts();$('courier-status-tabs').innerHTML=Object.entries(statusLabels).map(([id,label])=>`<button data-courier-status="${id}" class="${id===statusFilter?'active':''}">${label} <b>${c[id]}</b></button>`).join('');$('courier-status-tabs').querySelectorAll('button').forEach(b=>b.onclick=()=>{statusFilter=b.dataset.courierStatus;paint()})};
