 $('pricing-test').onclick=guard(async()=>{const d=payload();d.distance_m=Math.round(Number($('pricing-distance').value.replace(',','.'))*1000);d.return_required=$('pricing-return').checked;const result=await delivery('pricing_test',d);$('pricing-result').innerHTML=`<span>${esc(result.tariff_name)} · ${esc(result.scope==='merchant'?'personalizada':'cidade')} · versão ${result.tariff_version}</span><strong>${money(result.price_cents)}</strong><small>${money(result.subtotal_cents)} da rota${result.return_cents?' + '+money(result.return_cents)+' de retorno':''}</small>`});
