async function healthView(view){const h=await api('/health');view.innerHTML=`<section class="card"><h2>Configurações</h2>${[['Autenticação Supabase',h.auth_connected?'Conectada':'Indisponível'],['Novos cadastros',h.signup_disabled?'Desativados':'Permitidos'],['Confirmação de e-mail',h.email_confirmation?'Ativada':'Desativada'],['Cálculo de rotas',h.maps_configured?'Google Maps configurado':'Pendente'],['Carteiras e repasses',h.payments==='ledger_active'?'Razão interno ativo e auditável':'Pendente'],['Gateway de pagamentos',h.external_payments?'Asaas habilitado':'Desativado até homologação']].map(([a,b])=>`<div class="integration"><strong>${a}</strong><p>${b}</p></div>`).join('')}<p class="notice">Segredos e senhas nunca são exibidos no navegador.</p></section>`}
async function initialize(){const user=await auth.getUser(),status=await api('/status');$('admin-signout').hidden=false;if(!status.super_admin)throw Error('Acesso de superadministrador ainda não vinculado a esta conta.');cities=await api('/cities');$('admin-login').hidden=true;$('admin-app').hidden=false;document.body.classList.add('admin-authenticated');$('admin-identity').textContent=user.email;await render()}
